/**
 * Map of platform name -> publish record for every platform this item has been successfully published to. postId/permalink above only reflect the latest publish; this map is the cumulative list the UI shows.
 */
export type ContentItemPublishedPlatforms = {[key: string]: {
  /** @nullable */
  postId?: string | null;
  /** @nullable */
  permalink?: string | null;
  publishedAt: string;
}};

export interface ContentItem {
  id: number;
  title: string;
  caption: string;
  /** @nullable */
  imagePath?: string | null;
  /** @nullable */
  imagePrompt?: string | null;
  platform: string;
  contentType: string;
  status: string;
  /**
     * Why the last publish attempt failed. Set to a canonical restart-interruption message when the server auto-failed an orphaned "publishing" item, or a platform rejection message on a real publish failure. Null when not failed.
     * @nullable
     */
  failureReason?: string | null;
  /** @nullable */
  postId?: string | null;
  /** @nullable */
  permalink?: string | null;
  /** Map of platform name -> publish record for every platform this item has been successfully published to. postId/permalink above only reflect the latest publish; this map is the cumulative list the UI shows. */
  publishedPlatforms?: ContentItemPublishedPlatforms;
  /** How many LinkedIn follow-up comments from the last publish are still missing (0 when none). When > 0 the client can offer a "resend remaining comments" action. */
  linkedinCommentsPending?: number;
  /** How many Threads reply-chain posts from the last publish are still missing (0 when none). When > 0 the client can offer a "resend missing posts" action. */
  threadsPostsPending?: number;
  /** How many X thread posts from the last publish are still missing (0 when none). When > 0 the client can offer a "resend missing posts" action. */
  twitterPostsPending?: number;
  /** @nullable */
  brandKitId?: number | null;
  createdAt: string;
  updatedAt: string;
}

